/* CORRECTED. DP=$1D00. Only the four flagged areas changed; the rest of the
   spec's cPseudocode is verified correct and reproduced where relevant. */

/* ---- C0/9C37 z-gate: carry SET = SOLID. (UNCHANGED - verified correct) ---- */
bool zgate_solid(void) {
    if (R8($6C) != 0) {                 /* 9C39 BNE 9C53: IGNORE_Z tile */
        return R8($0155) == 3;          /* 9C56: solid iff player on transition plane 3 */
    }
    uint8 z = R8($6A);
    if (z == 0) return true;            /* 9C3D */
    if (z == 3) return false;           /* 9C41 */
    if (z == R8($0155)) return false;   /* 9C46 */
    if (R8($0155) == 3) return false;   /* 9C4D */
    return true;                        /* 9C4F SEC */
}

/* ---- C0/9C5C commit worker (tentative-pos + block UNCHANGED, verified) ---- */
void collision_commit(void) {          /* C0/9C5C, A16 */
    W16($66, R16($62) + R16($2E)); W16($70, R16($66));   /* 9C5E..9C65 */
    W16($68, R16($64) + R16($30));                       /* 9C67..9C6C */
    if (R16($30) & 0x0080)             /* 9C70 BIT #$0080: tests bit7 (NOT sign bit15) */
        W16($72, R16($68) - 0x0100);   /* 9C75..9C7B */
    else
        W16($72, R16($68) + 0x0100);   /* 9C7F..9C85 */
    SEP_A8();                           /* 9C89; A is 8-bit from here onward */
    R8($67);                            /* 9C8B cellX arg */
    propfetch_at_cell();                /* 9C8D JSR 9AC8 (see note) */
    shape_decode();                     /* 9C90 JSR 9AD3 */
    if (zgate_solid()) {                /* 9C93 JSR 9C37; 9C96 BCC */
        REP_A16(); W16($2E,0); W16($30,0); SEP_A8();     /* 9C98..9C9E BLOCK */
        return;                         /* 9CA0 RTS */
    }
    trigger_lookup_and_door();          /* 9CA1.. */
    plane_update();                     /* 9D54.. */
    W8($34, R8($5E));                   /* 9D6A..9D6C */
    conveyor_apply();                   /* 9D6E.. */
}

/* ---- C0/9CA1 trigger lookup: CORRECTED $7E7080 is an 8-BIT byte plane ---- */
void trigger_lookup_and_door(void) {
    if (R8($0117) & 0x80) goto L_9D2C;                  /* 9CA1..9CA8 */
    uint8 yi = R8($69) & R8($1F);                       /* 9CAB..9CAD */
    uint8 xi = R8($67) & R8($1E);                       /* 9CB0..9CB2 */
    REP_X16();
    uint16 X = ((uint16)yi << 8) | xi;                  /* 9CB6 TAX */
    uint8 idx = R8_long(0x7E7080 + X);  /* 9CB7 LDA $7E7080,X is 8-BIT (A8) */
    if (idx & 0x80) goto L_9D35;        /* 9CBB BMI: BIT7 sentinel = no trigger */
    WRMPYA = idx; WRMPYB = 7;           /* 9CBD..9CC2: full byte feeds the multiply */
    /* 9CC5-9CC7 NOP x3 multiply wait */
    REP_A16();
    uint16 rec = RDMPY() + R16($04);    /* 9CCA..9CD0 (16-bit RDMPYL + 16-bit dp $04/$05) */
    SEP_A8();
    X = rec;
    if (ROM8(0xE50000 + X) == R8($67)) {               /* 9CD3..9CD9 */
        int8 dy = ROM8(0xE50001 + X) - R8($69);        /* 9CE5..9CEA */
        if (dy < 0) dy = -dy;                           /* 9CEC..9CF0 */
        if ((uint8)dy >= 0x3F) goto L_9D2C;            /* 9CF1..9CF3 */
        goto L_arm;
    } else if (ROM8(0xE50001 + X) == R8($69)) {        /* 9CDB..9CE1 */
        goto L_arm;
    } else { goto L_9D2C; }                             /* 9CE3 */
L_arm: {                                                /* 9CF5..9D29 (UNCHANGED) */
        uint8 f = ROM8(0xE50004 + X); W8($52, f);
        W8($0116, (f >> 1) & 0x0F);
        W8($0116, R8($0116) | (f & 0x80));
        W8($0113, f & 0x01);
        W8($0112, ROM8(0xE50003 + X));
        W8($0114, ROM8(0xE50005 + X));
        W8($0115, ROM8(0xE50006 + X));
        W8($0117, R8($0117) | 0x80);
    }
L_9D2C: { /* dead recompute of primary index (9D2C..9D33), overwritten below */ }
L_9D35: {                                              /* door check on WRAP neighbour */
        uint8 yi3 = R8($73) & R8($1F);                  /* 9D35..9D39 */
        uint8 xi3 = R8($71) & R8($1E);                  /* 9D3A..9D3C */
        uint16 Xn = ((uint16)yi3 << 8) | xi3;           /* 9D3E TAX */
        if (R8_long(0x7E7000 + Xn) & 0x10) {            /* 9D3F..9D45 byte1 bit4 (8-bit load) */
            W16($015B, Xn);                             /* 9D47 STX (16-bit) */
            W8($0117, R8($0117) | 0x10);                /* 9D4A..9D4F */
        }
        SEP_X8();                                       /* 9D52 */
    }
}

/* ---- C0/9D54 plane update (UNCHANGED - verified) ---- */
void plane_update(void) {
    if (R8($6C) == 0) {                 /* 9D54..9D56 */
        W8($0155, R8($6A));             /* 9D58..9D5A */
        uint8 px = R8($0197);           /* 9D5D */
        W8(0x0C00 + px, R8($6E));       /* 9D60..9D62 */
        W8(0x0C01 + px, R8($6F));       /* 9D65..9D67 */
    }
}

/* ---- C0/9D6E conveyor (UNCHANGED - speed+dir+sign all verified) ---- */
void conveyor_apply(void) {
    uint8 sel = R8($5A) & 0x0C;
    if (sel == 0) { W8($2A,0); W8($2B,0); return; }     /* 9DBE */
    uint8 speed = (sel==0x04)?0x08 : (sel==0x08)?0x10 : 0x20;
    W8($52, speed);
    W8($34, R8($34) | 0x08);            /* 9D8C..9D8E TSB #$08 */
    switch (R8($5A) & 0x03) {           /* 9D90..9D9A DEC/DEC dispatch */
      case 0: W8($2B,(uint8)(0-speed)); W8($2A,0); return; /* 9DB4: $2B=-speed */
      case 1: W8($2B,speed);            W8($2A,0); return; /* 9DAD: $2B=+speed */
      case 2: W8($2A,(uint8)(0-speed)); W8($2B,0); return; /* 9DA3: $2A=-speed */
      case 3: W8($2A,speed);            W8($2B,0); return; /* 9D9C: $2A=+speed */
    }
}

/* ---- C0/9DC3 scene-load init: CORRECTED party 2/3 priority bytes ---- */
void scene_load_init(void) {
    W8($01AB,0); W8($01AC,0); W8($01AD,0);              /* 9DC3..9DC9 */
    W8_long(0x7F0C00,0); W8_long(0x7F0C80,0);
    W8_long(0x7F0D00,0); W8_long(0x7F0D80,0);           /* 9DCC..9DDA */
    PHD(); D = 0x1D00;                                  /* 9DDE..9DE4 */
    uint16 cell = R16($0102);                           /* 9DE5 (16-bit) */
    SEP_A8();
    propfetch_at_cell_lowbyte(cell);                    /* 9DEA JSR 9AC8 */
    W8($66, 0x80); W8($68, 0xFF);                       /* 9DED..9DF3 */
    shape_decode();                                     /* 9DF5 JSR 9AD3 */
    uint8 z = R8($6A); if (z == 0) z = 1;               /* 9DF8..9DFC */
    W8($0155, z);                                       /* 9DFE */
    /* PLAYER: ($6E,$6F) */
    uint8 a = R8($6E);                                  /* 9E01 LDA $6E */
    uint8 p0 = R8($0197);                               /* 9E03 LDX */
    W8(0x0C00 + p0, a);                                 /* 9E06 STA = $6E */
    a = R8($6F);                                        /* 9E09 LDA $6F (A := $6F, NOT reloaded again) */
    W8(0x0C01 + p0, a);                                 /* 9E0B STA = $6F */
    /* PARTY 2: BOTH bytes get A == $6F */
    uint8 p1 = R8($0199);                               /* 9E0E */
    W8(0x0C00 + p1, a);                                 /* 9E11 STA = $6F  (CORRECTED) */
    W8(0x0C01 + p1, a);                                 /* 9E14 STA = $6F */
    /* PARTY 3: BOTH bytes get A == $6F */
    uint8 p2 = R8($019B);                               /* 9E17 */
    W8(0x0C00 + p2, a);                                 /* 9E1A STA = $6F  (CORRECTED) */
    W8(0x0C01 + p2, a);                                 /* 9E1D STA = $6F */
    W8(0x1D34, R8($5E));                                /* 9E20..9E22 (== $34 under DP=$1D00) */
    PLD(); REP_X16();                                   /* 9E25..9E26 */
}

/* NOTE on support C0/9AC8: the AND $1E runs in 16-bit A mode (REP #$20 at
   9ACA), so it is a 16-bit AND of the full accumulator $69:$67 with the
   16-bit dp operand $1F:$1E, giving index (($69&$1F)<<8)|($67&$1E) -- the
   same de-interleave as the trigger lookup, NOT a single-byte cellX mask. */
